      "description": "Percentage of randomized+directed (a,b,sel) test vectors for which recovered_datapath output matches the reference gate_netlist.v output exactly, via iverilog/vvp simulation.",
      "direction": "maximize"
    }
  ],
  "baselines": [
    "HAL benchmarks",
    "ISCAS'85",
    "ITC'99"
  ],
